-- Refund workflows. Apply after phase20 checkout and phase15 RBAC.
alter table public.orders add column if not exists delivered_at timestamptz;
alter table public.orders add column if not exists refund_pricing_complete boolean not null default false;
update public.orders o set delivered_at=(select l.created_at from public.audit_logs l where l.table_name='orders' and l.row_id=o.id::text and l.action in ('order_status_updated','fulfilment_status_updated','UPDATE') and coalesce(l.payload->>'to',l.payload->>'status',l.payload->'new'->>'status')='delivered' order by l.created_at desc limit 1) where o.status='delivered' and o.delivered_at is null;
alter table public.order_items add column if not exists gst_amount numeric(12,2) not null default 0;
alter table public.order_items add column if not exists discount_amount numeric(12,2) not null default 0;
alter table public.refunds add column if not exists requested_by uuid references public.users(id);
alter table public.refunds add column if not exists status text not null default 'refunded';
alter table public.refunds add column if not exists comment text;
alter table public.refunds add column if not exists method text;
alter table public.refunds add column if not exists updated_at timestamptz not null default now();
alter table public.refunds add column if not exists decided_by uuid references public.users(id);
alter table public.refunds add column if not exists decided_at timestamptz;
alter table public.refunds add column if not exists decision_note text;
alter table public.refunds add column if not exists fee_amount numeric(12,2) not null default 0;
alter table public.refunds add column if not exists photo_paths text[] not null default '{}';
alter table public.refunds drop constraint if exists refunds_status_check;
alter table public.refunds add constraint refunds_status_check check(status in ('requested','approved','rejected','refunded'));
create table if not exists public.refund_items(id bigint generated by default as identity primary key, refund_id bigint not null references public.refunds(id) on delete cascade, order_item_id bigint not null references public.order_items(id), quantity integer not null check(quantity>0), amount numeric(12,2) not null check(amount>=0), unique(refund_id,order_item_id));
create table if not exists public.refund_events(id bigint generated by default as identity primary key, refund_id bigint not null references public.refunds(id) on delete cascade, from_status text, to_status text not null, actor_id uuid references public.users(id), note text, created_at timestamptz not null default now());
create index if not exists refunds_status_created_idx on public.refunds(status,created_at desc);
create index if not exists refunds_order_idx on public.refunds(order_id,created_at desc);
alter table public.refunds enable row level security;
alter table public.refund_items enable row level security;
alter table public.refund_events enable row level security;
drop policy if exists "customers read own refunds" on public.refunds;
create policy "customers read own refunds" on public.refunds for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()) or public.current_role() in ('store_manager','super_admin'));
drop policy if exists "customers insert own refunds" on public.refunds;
create policy "customers insert own refunds" on public.refunds for insert to authenticated with check(requested_by=auth.uid() and exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
drop policy if exists "refund items read scoped" on public.refund_items;
create policy "refund items read scoped" on public.refund_items for select to authenticated using(exists(select 1 from public.refunds r join public.orders o on o.id=r.order_id where r.id=refund_id and (o.user_id=auth.uid() or public.current_role() in ('store_manager','super_admin'))));
drop policy if exists "refund events read scoped" on public.refund_events;
create policy "refund events read scoped" on public.refund_events for select to authenticated using(exists(select 1 from public.refunds r join public.orders o on o.id=r.order_id where r.id=refund_id and (o.user_id=auth.uid() or public.current_role() in ('store_manager','super_admin'))));
revoke insert,update,delete on public.refunds,public.refund_items,public.refund_events from anon,authenticated;
grant select on public.refunds,public.refund_items,public.refund_events to authenticated;
insert into storage.buckets(id,name,public) values('refund-photos','refund-photos',false) on conflict(id) do nothing;
drop policy if exists "customers upload own refund photos" on storage.objects;
create policy "customers upload own refund photos" on storage.objects for insert to authenticated
 with check(bucket_id='refund-photos' and (storage.foldername(name))[1]='refunds' and (storage.foldername(name))[2]=auth.uid()::text);
drop policy if exists "refund participants read photos" on storage.objects;
create policy "refund participants read photos" on storage.objects for select to authenticated
 using(bucket_id='refund-photos' and (storage.foldername(name))[1]='refunds' and ((storage.foldername(name))[2]=auth.uid()::text or public.current_role() in ('store_manager','super_admin')));
drop policy if exists "customers delete own refund photos" on storage.objects;
create policy "customers delete own refund photos" on storage.objects for delete to authenticated
 using(bucket_id='refund-photos' and (storage.foldername(name))[1]='refunds' and (storage.foldername(name))[2]=auth.uid()::text);
do $$
begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='refunds') then alter publication supabase_realtime add table public.refunds; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='refund_events') then alter publication supabase_realtime add table public.refund_events; end if;
 end if;
end $$;

-- Preserve checkout behavior while snapshotting actual GST and proportional coupon discount per line.
create or replace function public.place_order(p_address_id bigint,p_items jsonb,p_payment_method text,p_delivery_slot text,p_coupon_code text)
returns bigint language plpgsql security definer set search_path=public as $$
declare oid bigint; item jsonb; pid bigint; requested_id bigint; v_sku text; pname text; qty int; price numeric; tax numeric; subtotal numeric:=0; gst_total numeric:=0; discount numeric:=0; delivery numeric:=0; packing numeric:=19; total numeric; item_count int; item_index int:=0; allocated_gst numeric:=0; allocated_discount numeric:=0; line_gst numeric; line_discount numeric;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if lower(trim(coalesce(p_payment_method,''))) not in ('prepaid','razorpay','cod') then raise exception 'INVALID_PAYMENT_METHOD'; end if;
 if p_address_id is null or not exists(select 1 from public.addresses where id=p_address_id and user_id=auth.uid()) then raise exception 'ADDRESS_REQUIRED'; end if;
 if jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'EMPTY_CART'; end if;
 for item in select * from jsonb_array_elements(p_items) loop
  requested_id:=nullif(item->>'product_id','')::bigint; v_sku:=nullif(item->>'sku',''); pname:=nullif(item->>'name',''); qty:=(item->>'quantity')::int;
  if qty is null or qty<1 then raise exception 'INVALID_QUANTITY'; end if;
  pid:=null; price:=null;
  if v_sku is not null then select id,selling_price,coalesce(gst,0) into pid,price,tax from public.products where public.products.sku=v_sku and is_active; end if;
  if price is null and pname is not null then select id,selling_price,coalesce(gst,0) into pid,price,tax from public.products where lower(public.products.name)=lower(pname) and is_active; end if;
  if price is null and requested_id is not null then select id,selling_price,coalesce(gst,0) into pid,price,tax from public.products where id=requested_id and is_active; end if;
  if pid is null or price is null then raise exception 'PRODUCT_NOT_FOUND'; end if;
  update public.inventory set current_stock=current_stock-qty where product_id=pid and current_stock-reserved_stock>=qty;
  if not found then raise exception 'INSUFFICIENT_STOCK:%',pid; end if;
  subtotal:=subtotal+price*qty; gst_total:=gst_total+price*qty*tax/100;
 end loop;
 if subtotal>=1000 then delivery:=0; else delivery:=49; end if;
 if nullif(trim(p_coupon_code),'') is not null then select c.discount into discount from public.customer_validate_coupon(p_coupon_code,subtotal) c where c.valid; end if;
 gst_total:=round(gst_total,2);
 total:=greatest(0,subtotal+gst_total+delivery+packing-discount);
 insert into public.orders(user_id,address_id,delivery_slot,total,refund_pricing_complete) values(auth.uid(),p_address_id,p_delivery_slot,total,true) returning id into oid;
 select count(*) into item_count from jsonb_array_elements(p_items); item_index:=0;
 for item in select * from jsonb_array_elements(p_items) loop
  requested_id:=nullif(item->>'product_id','')::bigint; v_sku:=nullif(item->>'sku',''); pname:=nullif(item->>'name',''); qty:=(item->>'quantity')::int; pid:=null;
  if v_sku is not null then select id into pid from public.products where public.products.sku=v_sku; end if;
  if pid is null and pname is not null then select id into pid from public.products where lower(public.products.name)=lower(pname); end if;
  if pid is null then pid:=requested_id; end if;
  select selling_price,coalesce(gst,0) into price,tax from public.products where id=pid;
  item_index:=item_index+1;
  if item_index=item_count then line_gst:=gst_total-allocated_gst; else line_gst:=round(price*qty*tax/100,2); allocated_gst:=allocated_gst+line_gst; end if;
  if item_index=item_count then line_discount:=discount-allocated_discount; else line_discount:=case when subtotal>0 then round(discount*price*qty/subtotal,2) else 0 end; allocated_discount:=allocated_discount+line_discount; end if;
  insert into public.order_items(order_id,product_id,quantity,unit_price,substitute_if_unavailable,gst_amount,discount_amount) values(oid,pid,qty,price,coalesce((item->>'substitute')::boolean,false),line_gst,line_discount);
 end loop;
 insert into public.payments(order_id,method,amount) values(oid,case when lower(trim(p_payment_method)) in ('prepaid','razorpay') then 'prepaid' else 'cod' end,total);
 delete from public.cart where user_id=auth.uid(); return oid;
end $$;
grant execute on function public.place_order(bigint,jsonb,text,text,text) to authenticated;

-- Server-side request: enforces ownership, delivered window, selected quantities and amount.
create or replace function public.create_refund_request(p_order_id bigint,p_reason text,p_comment text,p_items jsonb,p_photos text[] default '{}') returns bigint language plpgsql security definer set search_path=public as $$
declare o public.orders%rowtype; r bigint; it record; li record; amt numeric:=0; line_amt numeric; prior_qty integer; prior_amt numeric; fee_amt numeric:=0; method_name text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_reason not in ('Damaged or defective','Wrong item','Not as described','Changed my mind','Other') then raise exception 'INVALID_REASON'; end if;
 if p_reason='Other' and nullif(trim(p_comment),'') is null then raise exception 'COMMENT_REQUIRED'; end if;
 select * into o from public.orders where id=p_order_id and user_id=auth.uid() for update;
 if not found then raise exception 'ORDER_NOT_FOUND'; end if;
 if o.status<>'delivered' then raise exception 'ORDER_NOT_DELIVERED'; end if;
 if not o.refund_pricing_complete then raise exception 'REFUND_PRICING_UNAVAILABLE'; end if;
 if o.delivered_at is null or o.delivered_at<now()-interval '7 days' then raise exception 'RETURN_WINDOW_CLOSED'; end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'SELECT_ITEMS'; end if;
 if cardinality(coalesce(p_photos,'{}'))>3 then raise exception 'TOO_MANY_PHOTOS'; end if;
 if exists(select 1 from unnest(coalesce(p_photos,'{}')) as photos(path) where path not like 'refunds/'||auth.uid()::text||'/%' or not exists(select 1 from storage.objects so where so.bucket_id='refund-photos' and so.name=photos.path)) then raise exception 'INVALID_REFUND_PHOTO'; end if;
 if exists(select 1 from jsonb_array_elements(p_items) j where coalesce((j->>'quantity')::int,0)<=0) then raise exception 'INVALID_QUANTITY'; end if;
 if exists(select 1 from jsonb_array_elements(p_items) j group by (j->>'order_item_id')::bigint having count(*)>1) then raise exception 'DUPLICATE_ITEM'; end if;
 for it in select (j->>'order_item_id')::bigint item_id,(j->>'quantity')::int qty from jsonb_array_elements(p_items) j loop
   select id,quantity,unit_price,gst_amount,discount_amount into li from public.order_items where id=it.item_id and order_id=p_order_id;
   if not found or it.qty>li.quantity then raise exception 'INVALID_ORDER_ITEM'; end if;
   if it.qty+coalesce((select sum(ri.quantity) from public.refund_items ri join public.refunds rf on rf.id=ri.refund_id where ri.order_item_id=li.id and rf.status<>'rejected'),0)>li.quantity then raise exception 'ITEM_ALREADY_REQUESTED'; end if;
   select coalesce(sum(ri.quantity),0),coalesce(sum(ri.amount),0) into prior_qty,prior_amt from public.refund_items ri join public.refunds rf on rf.id=ri.refund_id where ri.order_item_id=li.id and rf.status<>'rejected';
   if prior_qty+it.qty=li.quantity then line_amt:=round(li.unit_price*li.quantity+li.gst_amount-li.discount_amount,0)-prior_amt;
   else line_amt:=round(((li.unit_price*li.quantity+li.gst_amount-li.discount_amount)/li.quantity)*it.qty,0); end if;
   amt:=amt+line_amt;
 end loop;
 if p_reason in ('Damaged or defective','Wrong item','Not as described') then
   select greatest(0,o.total-(select coalesce(sum(oi.unit_price*oi.quantity+oi.gst_amount-oi.discount_amount),0) from public.order_items oi where oi.order_id=p_order_id)-coalesce(sum(rf.fee_amount),0)) into fee_amt from public.refunds rf where rf.order_id=p_order_id and rf.status<>'rejected';
   amt:=amt+fee_amt;
 end if;
 select p.method into method_name from public.payments p where p.order_id=p_order_id order by p.id desc limit 1;
 insert into public.refunds(order_id,requested_by,status,reason,comment,amount,fee_amount,method,photo_paths) values(p_order_id,auth.uid(),'requested',p_reason,left(p_comment,300),greatest(0,amt),fee_amt,case when lower(coalesce(method_name,'')) in ('cod','cash on delivery') then 'Store credit or bank transfer' else 'Original payment method' end,coalesce(p_photos,'{}')) returning id into r;
 insert into public.refund_events(refund_id,from_status,to_status,actor_id) values(r,null,'requested',auth.uid());
 insert into public.refund_items(refund_id,order_item_id,quantity,amount) select r,(j->>'order_item_id')::bigint,(j->>'quantity')::int,case when coalesce((select sum(pri.quantity) from public.refund_items pri join public.refunds pr on pr.id=pri.refund_id where pri.order_item_id=oi.id and pr.status<>'rejected'),0)+(j->>'quantity')::int=oi.quantity then round(oi.unit_price*oi.quantity+oi.gst_amount-oi.discount_amount,0)-coalesce((select sum(pri.amount) from public.refund_items pri join public.refunds pr on pr.id=pri.refund_id where pri.order_item_id=oi.id and pr.status<>'rejected'),0) else round(((oi.unit_price*oi.quantity+oi.gst_amount-oi.discount_amount)/oi.quantity)*(j->>'quantity')::int,0) end from jsonb_array_elements(p_items) j join public.order_items oi on oi.id=(j->>'order_item_id')::bigint;
 return r;
end $$;
revoke all on function public.create_refund_request(bigint,text,text,jsonb,text[]) from public,anon;
grant execute on function public.create_refund_request(bigint,text,text,jsonb,text[]) to authenticated;

create or replace function public.set_refund_status(p_refund_id bigint,p_status text,p_note text default null) returns boolean language plpgsql security definer set search_path=public as $$
declare old_status text; oid bigint; customer uuid;
begin
 if public.current_role() not in ('store_manager','super_admin') then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_status not in ('approved','rejected','refunded') then raise exception 'INVALID_REFUND_STATUS'; end if;
 if p_status='rejected' and nullif(trim(p_note),'') is null then raise exception 'REJECTION_NOTE_REQUIRED'; end if;
 select status,order_id into old_status,oid from public.refunds where id=p_refund_id for update;
 if not found then raise exception 'REFUND_NOT_FOUND'; end if;
 if not ((old_status='requested' and p_status in ('approved','rejected')) or (old_status='approved' and p_status='refunded')) then raise exception 'INVALID_REFUND_STEP'; end if;
 update public.refunds set status=p_status,updated_at=now(),decided_by=auth.uid(),decided_at=now(),decision_note=case when p_status='rejected' then left(trim(p_note),500) else decision_note end where id=p_refund_id returning requested_by into customer;
 insert into public.refund_events(refund_id,from_status,to_status,actor_id,note) values(p_refund_id,old_status,p_status,auth.uid(),case when p_status='rejected' then left(trim(p_note),500) end);
 if customer is not null then insert into public.notifications(user_id,title,body) values(customer,'Refund update','Refund for order #'||oid||' is now '||p_status||case when p_status='rejected' then ': '||left(trim(p_note),300) else '.' end); end if;
 if p_status='refunded' and not exists(select 1 from public.order_items oi where oi.order_id=oid and oi.quantity>coalesce((select sum(ri.quantity) from public.refund_items ri join public.refunds rf on rf.id=ri.refund_id where ri.order_item_id=oi.id and rf.status='refunded'),0)) then update public.orders set status='refunded' where id=oid and status in ('delivered','returned','cancelled'); end if;
 return true;
end $$;
revoke all on function public.set_refund_status(bigint,text,text) from public,anon;
grant execute on function public.set_refund_status(bigint,text,text) to authenticated;

-- Permit the existing order-level Refunded label once every ordered unit is refunded.
create or replace function public.enforce_order_status_permission()
returns trigger language plpgsql security definer set search_path=public as $$
declare role_name text:=public.current_role();
begin
 if new.status is not distinct from old.status or auth.uid() is null then return new; end if;
 if role_name='picker' then
  if old.status<>'picking' or new.status<>'packed' then raise exception 'FORBIDDEN_STATUS_TRANSITION' using errcode='42501'; end if;
 elsif role_name in ('store_manager','super_admin') then
  if not ((old.status='placed' and new.status in ('accepted','cancelled')) or (old.status='accepted' and new.status in ('picking','cancelled')) or (old.status='picking' and new.status='packed') or (old.status='packed' and new.status='out_for_delivery') or (old.status='out_for_delivery' and new.status='delivered') or (old.status='delivered' and new.status='returned') or (new.status='refunded' and old.status in ('cancelled','returned','delivered'))) then raise exception 'INVALID_STATUS_TRANSITION' using errcode='22023'; end if;
 else raise exception 'FORBIDDEN_STATUS_TRANSITION' using errcode='42501'; end if;
 return new;
end $$;

-- Stamp delivered_at for new deliveries. Older delivered orders use created_at as fallback.
create or replace function public.stamp_order_delivered_at() returns trigger language plpgsql set search_path=public as $$
begin
 if new.status='delivered' and old.status is distinct from 'delivered' then new.delivered_at:=coalesce(new.delivered_at,now()); end if;
 return new;
end $$;
drop trigger if exists order_delivered_at_stamp on public.orders;
create trigger order_delivered_at_stamp before update of status on public.orders for each row execute function public.stamp_order_delivered_at();

-- Any prepaid pre-dispatch cancellation receives a full paid-amount demo refund.
create or replace function public.auto_refund_prepaid_cancellation() returns trigger language plpgsql security definer set search_path=public as $$
declare p record; r bigint;
begin
 if new.status='cancelled' and old.status is distinct from 'cancelled' then
  select * into p from public.payments where order_id=new.id order by id desc limit 1;
  if p.method is not null and lower(p.method) not in ('cod','cash on delivery') and not exists(select 1 from public.refunds where order_id=new.id and status<>'rejected') then
   insert into public.refunds(order_id,requested_by,status,reason,amount,fee_amount,method,decided_by,decided_at) values(new.id,new.user_id,'refunded','Order cancelled before dispatch',p.amount,greatest(0,p.amount-(select coalesce(sum(oi.unit_price*oi.quantity+oi.gst_amount-oi.discount_amount),0) from public.order_items oi where oi.order_id=new.id)),'Original payment method',auth.uid(),now()) returning id into r;
   insert into public.refund_events(refund_id,from_status,to_status,actor_id) values(r,null,'refunded',auth.uid());
   insert into public.refund_items(refund_id,order_item_id,quantity,amount) select r,id,quantity,round(unit_price*quantity+gst_amount-discount_amount,0) from public.order_items where order_id=new.id;
   update public.payments set status='refunded' where order_id=new.id;
  end if;
 end if;
 return new;
end $$;
drop trigger if exists prepaid_cancel_refund on public.orders;
create trigger prepaid_cancel_refund after update of status on public.orders for each row execute function public.auto_refund_prepaid_cancellation();

-- Retain the established cancellation and stock-restoration behavior. Refund processing itself never touches inventory.
create or replace function public.customer_cancel_order(p_order_id bigint) returns boolean language plpgsql security definer set search_path=public as $$
declare v_status public.order_status;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 select status into v_status from public.orders where id=p_order_id and user_id=auth.uid() for update;
 if v_status is null then raise exception 'ORDER_NOT_FOUND'; end if;
 if v_status not in ('placed','accepted') then raise exception 'ORDER_CANNOT_BE_CANCELLED'; end if;
 update public.orders set status='cancelled',cancelled_at=coalesce(cancelled_at,now()) where id=p_order_id;
 update public.inventory i set current_stock=i.current_stock+items.quantity,warehouse_stock=i.warehouse_stock+items.quantity from (select product_id,sum(quantity)::integer quantity from public.order_items where order_id=p_order_id group by product_id) items where i.product_id=items.product_id;
 insert into public.audit_logs(actor_id,action,table_name,row_id,payload) values(auth.uid(),'order_cancelled_by_customer','orders',p_order_id::text,'{}'::jsonb);
 return true;
end $$;
grant execute on function public.customer_cancel_order(bigint) to authenticated;
